// This script reads SQL files from ./migrations/ and logs each filename it would apply, in order.
const fs = require('fs');
const path = require('path');

const migrationsDir = './migrations';

try {
  // Read all files in the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files and sort them alphabetically (to ensure order)
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();

  // Log each migration file that would be applied
  console.log('Migrations to be applied:');
  sqlFiles.forEach(file => {
    console.log(`- ${file}`);
  });

  if (sqlFiles.length === 0) {
    console.log('No SQL files found in the migrations directory.');
  }
} catch (err) {
  if (err.code === 'ENOENT') {
    console.error(`Migrations directory not found: ${migrationsDir}`);
  } else {
    console.error('Error reading migrations directory:', err.message);
  }
}

