const fs = require('fs');
const path = require('path');

const migrationsDir = './migrations';

// Load environment variables from .env.test
function loadEnv() {
  const envFile = '.env.test';

  try {
    const envContent = fs.readFileSync(envFile, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse KEY=VALUE lines
      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('='); // Handle values that contain =

      if (key && value !== undefined) {
        // Remove quotes from value if present
        const cleanedValue = value.trim().replace(/^['"](.*)['"]$/, '$1');
        process.env[key.trim()] = cleanedValue;
      }
    }

    console.log('Loaded environment from .env.test');
  } catch (error) {
    console.error('Error loading .env.test:', error);
    process.exit(1);
  }
}

function runMigrations() {
  // Load environment variables
  loadEnv();

  // Get database URL
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    console.error('DATABASE_URL not found in .env.test');
