const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Reads environment variables from a file
 * @param {string} filePath - Path to the environment file
 * @returns {Object} Parsed environment variables
 */
function readEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      throw new Error(`Environment file not found: ${filePath}`);
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    // Parse each line
    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.trim().startsWith('#')) {
        return;
      }

      // Split on the first equals sign
      const separatorIndex = line.indexOf('=');
      if (separatorIndex === -1) {
        return; // Skip lines without equals
      }

      const key = line.substring(0, separatorIndex).trim();
      let value = line.substring(separatorIndex + 1).trim();

      // Remove surrounding quotes if present
      if (value.startsWith('"') && value.endsWith('"')) {
        value = value.substring(1, value.length - 1);
      }

      env[key] = value;
    });

    return env;
  } catch (error) {
    throw new Error(`Error reading environment file: ${error.message}`);
  }
}

/**
 * Reads SQL files from the migrations directory and logs each filename in order
 */
async function runMigrations() {
  try {
    // Read database connection string from .env.test
    let dbUrl = '';
    try {
