// migrate.js
// This script reads SQL files from the ./migrations/ directory and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

const migrationsDir = './migrations';

try {
  // Read all files from the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter out only .sql files and sort them alphabetically (which should be by version/order)
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();

  // Log each migration file that would be applied
  console.log('Migrations to be applied:');
  sqlFiles.forEach(file => {
    console.log(`- ${file}`);
  });

} catch (error) {
  console.error('Error reading migrations directory:', error.message);
}

// migrate.js
// This script reads SQL files from the ./migrations/ directory and logs each filename it would apply, in order.
// It also reads DATABASE_URL from .env.test and logs a connection message.

const fs = require('fs');
const path = require('path');

const migrationsDir = './migrations';
const envFile = '.env.test';

try {
  // Try to read the .env.test file
  let databaseUrl = null;
  try {
    const envContent = fs.readFileSync(envFile, 'utf8');
    const envLines = envContent.split('\n');

    // Look for DATABASE_URL in the file
    for (const line of envLines) {
      const trimmedLine = line.trim();
      // Skip comments and empty lines
      if (trimmedLine && !trimmedLine.startsWith('#')) {
        const [key, value] = trimmedLine.split('=', 2);
        if (key && value && key.trim() === 'DATABASE_URL') {
          databaseUrl = value.trim().replace(/['"]+/g, ''); // Remove quotes if present
          break;
        }
      }
    }

    if (databaseUrl) {
      console.log(`Connected successfully to database: ${databaseUrl}`);
    } else {
      console.log('DATABASE_URL not found in .env.test, proceeding without database connection info');
    }
  } catch (envError) {
    console.log('.env.test file not found or could not be read, proceeding without database connection info');
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter out only .sql files and sort them alphabetically (which should be by version/order)
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();

  // Log each migration file that would be applied
  console.log('\nMigrations to be applied:');
  sqlFiles.forEach(file => {
    console.log(`- ${file}`);
  });

} catch (error) {
  console.error('Error during migration process:', error.message);
}
